```xs
fn describe(shape) {
    return match shape {
        Shape::Circle(r) => "circle r={r}"
        Shape::Rect(w, h) => "rect {w}x{h}"
        Shape::Triangle(a, b, c) => "triangle {a},{b},{c}"
